head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil17200";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil17200.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/common/irDataFileDown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {*} filename filename
 * @param {*} realFilename realFilename
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (filename, realFilename) {
    $c.util.getComponent('dma_FileDownReq').set('method', 'popupFileDown');
    (document.fileDownForm || { elements: [] }).action = '/common/irDataFileDown.do';
    $c.util.getComponent('dma_FileDownReq').set('filename', filename);
    $c.util.getComponent('dma_FileDownReq').set('realFilename', realFilename);
    const nr = await scwin.tx_fn_FileDown();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/basicpopup/basicpopup.xml", { "method": 'popupFileDown', "filename": filename, "realFilename": realFilename });
    }
};
